// Generates src/version.ts from the version in package.json.
// Importing package.json from src would move the tsc output to dist/src.
const { readFileSync, writeFileSync } = require('fs');
const { join } = require('path');

const root = join(__dirname, '..');
const { version } = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'));
const content =
  '// Generated by scripts/write-version.js. Do not edit.\n' +
  '\n' +
  '/**\n' +
  ' * The version of this package. Useful as a part of cache keys.\n' +
  ' */\n' +
  `export const VERSION = '${version}';\n`;

writeFileSync(join(root, 'src/version.ts'), content);
